using System.ComponentModel.DataAnnotations;
using System.ComponentModel.DataAnnotations.Schema;

namespace SKVI.Domain.Entities
{
    [Table("DailyStudyTasks")]
    public class DailyStudyTask
    {
        [Key]
        public Guid Id { get; set; } = Guid.NewGuid();

        public Guid PlanId { get; set; }

        public DateTime TaskDate { get; set; }

        [Required]
        public string Title { get; set; } = string.Empty;

        // The task description/content generated by AI
        [Required]
        public string Content { get; set; } = string.Empty;

        public string TaskType { get; set; } = "STUDY";

        public int EstimatedMinutes { get; set; } = 20;

        public int SortOrder { get; set; }

        public string Status { get; set; } = "PLANNED";

        public Guid? RelatedCourseId { get; set; }

        public Guid? RelatedLessonPartId { get; set; }

        public string ReflectionPrompt { get; set; } = string.Empty;

        public bool IsCompleted { get; set; } = false;

        // Feedback from the user after completing (e.g. "It was too hard", "I learned a lot")
        public string UserFeedback { get; set; } = string.Empty;

        // AI's advice/feedback based on the user's feedback
        public string AiAdvice { get; set; } = string.Empty;

        public int? ActualMinutesSpent { get; set; }

        public int? DifficultyRating { get; set; }

        public int? ConfidenceRating { get; set; }

        public bool NeedsSupport { get; set; }

        public DateTime? CompletedAt { get; set; }

        public DateTime CreatedAt { get; set; } = DateTime.UtcNow;

        [ForeignKey("PlanId")]
        public virtual UserStudyPlan Plan { get; set; } = null!;

        [ForeignKey(nameof(RelatedCourseId))]
        public virtual Course? RelatedCourse { get; set; }

        [ForeignKey(nameof(RelatedLessonPartId))]
        public virtual LessonPart? RelatedLessonPart { get; set; }
    }
}
